<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Mail/MessageBody.php';require_once dirname(__DIR__).'/app/UI/Conversation.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';
require dirname(__DIR__).'/app/Admin/Users.php';
require dirname(__DIR__).'/app/Admin/Recovery.php';
require_once dirname(__DIR__).'/app/Mail/InternalMail.php';
require_once dirname(__DIR__).'/app/Mail/Router.php';
use TNL\Admin\Users;
use TNL\Admin\Recovery;
use TNL\Mail\InternalMail;
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https:; frame-src 'self'; form-action 'self'; base-uri 'self'; frame-ancestors 'self'");
if(!is_file(tnl_path('storage/system.sqlite'))){header('Location: ../install.php');exit;}
tnl_session();$db=tnl_db();Users::init($db);Recovery::init($db);
if(!isset($_SESSION['employee_id'])){header('Location: employee.php');exit;}
$id=(int)$_SESSION['employee_id'];
$s=$db->prepare('SELECT id,display_name,credentials_version,must_change_password FROM users WHERE id=? AND active=1');
$s->execute([$id]);$me=$s->fetch(PDO::FETCH_ASSOC);
if(!$me||(int)$me['credentials_version']!==(int)($_SESSION['credentials_version']??0)){unset($_SESSION['employee_id'],$_SESSION['credentials_version']);header('Location: employee.php');exit;}
if((int)$me['must_change_password']===1){header('Location: recovery.php');exit;}
$error='';$notice='';$folder=in_array($_GET['folder']??'',['sent','archive'],true)?$_GET['folder']:'inbox';
if($_SERVER['REQUEST_METHOD']==='POST'){
 tnl_check_csrf();
 try{
  if(($_POST['action']??'')==='send'){
   \TNL\Mail\Router::send($db,'employee:'.$id,$id,(string)($_POST['recipient']??''),(string)($_POST['subject']??''),(string)($_POST['body']??''),false,fn()=>throw new RuntimeException('Esta pantalla solo admite correo interno.'),isset($_POST['reply_to_id'])?(int)$_POST['reply_to_id']:null,'html');
   $notice='Mensaje interno enviado.';
  }elseif(in_array($_POST['action']??'',['archive','unarchive'],true)){
   InternalMail::archive($db,$id,(int)($_POST['message_id']??0),$_POST['action']==='archive');$notice='Carpeta actualizada.';
  }elseif(($_POST['action']??'')==='delete'){
   InternalMail::delete($db,$id,(int)($_POST['message_id']??0));$notice='Mensaje eliminado de tu bandeja.';
  }
 }catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo completar la operación.';}
}
$message=isset($_GET['id'])?InternalMail::read($db,$id,(int)$_GET['id']):null;
$messages=InternalMail::list($db,$id,$folder);
$replyTo=($message&&(int)$message['sender_id']!==$id)?$message:null;
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/app.css?v=0.8.1"><script src="assets/workspace.js?v=0.8.1" defer></script><link rel="stylesheet" href="assets/jodit/jodit.min.css"><script src="assets/jodit/jodit.min.js" defer></script><script src="assets/composer.js?v=0.8.1" defer></script><title>Correo del equipo · TNL Mail</title></head><body class="<?=($_GET['modal']??'')==='1'?'composer-popup':''?>" data-composer-result="<?=($_GET['modal']??'')==='1'&&$notice==='Mensaje interno enviado.'?'sent':''?>"><div class="layout"><?php \TNL\UI\Workspace::sidebar('employee','internal',(string)$me['display_name']);?><main class="main"><header class="page-header"><div><span class="eyebrow">TU EMPRESA · CORREO INTERNO</span><h1><?=['sent'=>'Enviados al equipo','archive'=>'Archivo del equipo','inbox'=>'Correo del equipo'][$folder]?></h1><p class="page-description">Conversaciones con las personas de tu empresa.</p></div><div class="page-actions"><a data-compose-modal class="button" href="?modal=1&amp;folder=<?=tnl_escape($folder)?>&amp;compose=1#internal-compose"><?=\TNL\UI\Workspace::icon('compose')?> Redactar</a></div></header><div class="mail-toolbar"><nav class="mail-tabs" aria-label="Carpetas internas"><a class="mail-tab <?=$folder==='inbox'?'active':''?>" href="mail.php">Entrada</a><a class="mail-tab <?=$folder==='sent'?'active':''?>" href="mail.php?folder=sent">Enviados</a><a class="mail-tab" href="mail.php?folder=archive">Archivo</a></nav><span class="badge">Solo tu equipo</span></div>
<?php if($error):?><p class="error" role="alert"><?=tnl_escape($error)?></p><?php endif;?><?php if($notice):?><p class="notice" role="status"><?=tnl_escape($notice)?></p><?php endif;?>
<?php if($message):?><article class="panel message-panel"><header class="message-heading"><div><h2><?=tnl_escape($message['subject'])?></h2><div class="message-meta"><span>De: <?=tnl_escape($message['sender_name'].' <'.$message['sender_address'].'>')?></span><span><?=tnl_escape($message['created_at'])?></span></div></div><?php if($replyTo):?><a class="button button-secondary" data-compose-modal href="?id=<?=(int)$message['id']?>&amp;compose=1&amp;modal=1">Responder</a><?php endif;?></header><?php $html=\TNL\Mail\MessageBody::html($message['body'],$message['format']);if($html!==''):?><iframe class="mail-html-view" title="Contenido del correo" sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox" data-mail-view srcdoc="<?=tnl_escape(\TNL\UI\MessageHtml::document(['html'=>$html],true))?>"></iframe><?php else:?><pre class="message-text"><?=tnl_escape($message['body'])?></pre><?php endif;?><footer class="message-footer"><a class="button button-secondary" href="print.php?kind=internal&amp;id=<?=(int)$message['id']?>" target="_blank" rel="noopener">Imprimir / PDF</a><a href="mail.php?folder=<?=tnl_escape($folder)?>">← Volver a la bandeja</a><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="message_id" value="<?=(int)$message['id']?>"><div><button class="button-danger">Eliminar de mi bandeja</button></div></form></footer></article><?php $thread=[];foreach(\TNL\Mail\InternalMail::conversation($db,$id,(int)$message['id']) as $part)$thread[]=['headers'=>['from'=>$part['sender_name'].' <'.$part['sender_address'].'>','date'=>$part['created_at'],'message-id'=>'<internal-'.$part['id'].'@tnl.invalid>'],'body'=>\TNL\Mail\MessageBody::plain($part['body'],$part['format']),'html'=>\TNL\Mail\MessageBody::html($part['body'],$part['format'])];\TNL\UI\Conversation::render($thread,true,'<internal-'.$message['id'].'@tnl.invalid>');?><?php else:?><section class="panel mail-surface"><?php if($messages):?><div class="mail-list-heading"><span><?=$folder==='sent'?'Destinatario':'Remitente'?></span><span>Asunto</span><span>Fecha</span></div><div class="mail-list"><?php foreach($messages as $m):?><div class="mail-row-wrap"><input type="checkbox" class="mail-select" aria-label="Seleccionar mensaje"><button type="button" class="mail-actions-toggle button-ghost" aria-label="Acciones del mensaje" aria-expanded="false" data-mail-actions>⋯</button><a class="mail-row <?=$m['read_at']===null&&$folder==='inbox'?'unread':''?>" href="?folder=<?=tnl_escape($folder)?>&amp;id=<?=(int)$m['id']?>"><span class="mail-sender" title="<?=tnl_escape($m['peer_address'])?>"><?=tnl_escape($m['peer_name'])?></span><span class="mail-subject"><?=tnl_escape($m['subject'])?><?=$m['read_at']===null&&$folder==='inbox'?' · Sin leer':''?></span><time class="mail-date"><?=tnl_escape($m['created_at'])?></time></a><form method="post" class="mail-row-actions"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="message_id" value="<?=(int)$m['id']?>"><a class="button button-ghost" href="print.php?kind=internal&amp;id=<?=(int)$m['id']?>" target="_blank" rel="noopener">Imprimir / PDF</a><button class="button-ghost" name="action" value="<?=$folder==='archive'?'unarchive':'archive'?>"><?=$folder==='archive'?'Restaurar':'Archivar'?></button><button class="button-ghost" name="action" value="delete">Borrar</button></form></div><?php endforeach;?></div><?php else:?><div class="empty-state"><span class="card-icon"><?=\TNL\UI\Workspace::icon('mail')?></span><h2>No hay mensajes en esta carpeta</h2><p>Escribe a alguien de tu equipo para comenzar una conversación.</p></div><?php endif;?></section><?php endif;?>
<?php if(($_GET['modal']??'')==='1'||isset($_GET['compose'])):?><details class="panel composer" id="internal-compose" <?=($replyTo||isset($_GET['compose']))?'open':''?>><summary class="compose-summary"><?=\TNL\UI\Workspace::icon('compose')?> <?=$replyTo?'Responder al mensaje':'Redactar un mensaje al equipo'?></summary><form method="post"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="action" value="send"><?php if($replyTo):?><input type="hidden" name="reply_to_id" value="<?=(int)$replyTo['id']?>"><?php endif;?><label>Para<input type="text" name="recipient" required placeholder="Escribe usuario, nombre o cargo" autocomplete="off" data-directory value="<?=tnl_escape($replyTo?(string)$replyTo['sender_address']:'')?>"></label><label>Asunto<input name="subject" maxlength="200" required value="<?=tnl_escape($replyTo?'Re: '.$replyTo['subject']:'')?>"></label><input type="hidden" name="format" value="html"><label>Mensaje<textarea data-rich-editor name="body" rows="10" maxlength="50000" required placeholder="Escribe tu mensaje aquí…"></textarea></label><div class="form-actions"><small>Este mensaje solo se enviará dentro de tu empresa.</small><button><?=\TNL\UI\Workspace::icon('send')?> Enviar mensaje</button></div></form></details><?php endif;?></main></div></body></html>
